-- Module 13, Lab 4 - Post-alter sample data updates
-- Run this script AFTER adding the new profile and attachment columns.
-- Uses the existing sample employees and leave requests from tms_sample_data (1).sql.
-- Employee photos are fictional PNG avatars encoded as Base64 CLOB values.
-- Leave attachments are fictional PDF documents encoded as Base64 CLOB values.
-- Recommended: SQL Workshop > SQL Scripts > Upload and Run.
-- Each update is committed before the next one to release row locks promptly.
-- If a run is interrupted, rerun the script to finish applying these fixed sample values.

SET DEFINE OFF;

UPDATE tms_employees
   SET phone                   = '+1-555-0101',
       emergency_contact_name  = 'Arun Patel',
       emergency_contact_phone = '+1-555-1101',
       photo_blob              = apex_web_service.clobbase642blob(
        TO_CLOB('') ||
        TO_CLOB('')
       ),
       photo_mime_type         = 'image/png',
       photo_filename          = 'maya_patel.png'
 WHERE email = 'maya.patel@acme.example';
COMMIT;

