UPDATE tms_leave_requests lr
   SET lr.attachment_blob = apex_web_service.clobbase642blob(
        TO_CLOB('')
        || TO_CLOB('')
       ),
       lr.attachment_mime_type = 'application/pdf',
       lr.attachment_filename  = 'maya_patel_leave_attachment.pdf'
 WHERE lr.employee_id = (
         SELECT e.employee_id
           FROM tms_employees e
          WHERE e.email = 'maya.patel@acme.example'
       )
   AND lr.start_date = DATE '2026-07-08'
   AND lr.end_date   = DATE '2026-07-12';
COMMIT;

