-- Verify employee profile sample data
SELECT employee_id,
       first_name || ' ' || last_name AS employee_name,
       phone,
       emergency_contact_name,
       emergency_contact_phone,
       photo_mime_type,
       photo_filename,
       DBMS_LOB.GETLENGTH(photo_blob) AS photo_bytes
  FROM tms_employees
 ORDER BY employee_id;

-- Verify leave-request attachment sample data
SELECT lr.request_id,
       e.first_name || ' ' || e.last_name AS employee_name,
       lr.start_date,
       lr.end_date,
       lr.status,
       lr.attachment_filename,
       lr.attachment_mime_type,
       DBMS_LOB.GETLENGTH(lr.attachment_blob) AS attachment_bytes
  FROM tms_leave_requests lr
  JOIN tms_employees e ON e.employee_id = lr.employee_id
 ORDER BY lr.request_id;
